import numpy as np
from math import comb
def pass_at_k(n, c, k):
    """n 번 뽑아 c 번 통과했을 때 pass@k 의 불편 추정 (Chen+ 2021)"""
    if n - c < k:
        return 1.0
    # 1 - C(n-c,k)/C(n,k) 를 곱으로 — 큰 n 에서 넘치지 않게
    return 1.0 - np.prod(1.0 - k / np.arange(n - c + 1, n + 1))
def pass_hat_k(n, c, k):                 # k 번 모두 성공할 확률 (일관성)
    return comb(c, k) / comb(n, k)
n, c = 10, 3
for k in [1, 2, 5]:
    naive = 1 - (1 - c / n) ** k
    print(k, round(pass_at_k(n, c, k), 4), round(1 - comb(n-c, k)/comb(n, k), 4),
          "naive", round(naive, 4), "pass^k", round(pass_hat_k(n, c, k), 4))
# 과제 여러 개의 평균이 벤치마크 점수
results = [(10, 0), (10, 3), (10, 10), (10, 1)]
print("pass@1 =", np.mean([pass_at_k(n, c, 1) for n, c in results]))
